const express = require('express');
const app = express();
const port = 3000;

app.get('/', (req, res) => {
  res.send('Welcome to the Webshop!');
});

app.get('/products', (req, res) => {
  const products = [
    { id: 1, name: 'Book', price: 20 },
    { id: 2, name: 'Pen', price: 2 },
    { id: 3, name: 'Notebook', price: 5 }
  ];
  res.json(products);
});

app.listen(port, () => {
  console.log(`Webshop listening at http://localhost:${port}`);
});

